        if ((!isfinite(w[i])) || (w[i] <= 0.0)) {
            *out = identity;
            return ADCS_E_RANGE;
        }

        // Normalize body vector
        if (!adcs_is_finite_vec3(&b[i]) || 
            adcs_vec3_normalize(&b[i], ADCS_EPS_NORM, &bn) != ADCS_OK) {
            *out = identity;
            return ADCS_E_RANGE;
        }

        // Normalize inertial vector
        if (!adcs_is_finite_vec3(&r[i]) || 
            adcs_vec3_normalize(&r[i], ADCS_EPS_NORM, &rn) != ADCS_OK) {
            *out = identity;
            return ADCS_E_RANGE;
        }

        weight_sum += w[i];

        // Accumulate B matrix: sum(w_i * outer(bn_i, rn_i))
        adcs_mat3_t outer = adcs_mat3_outer(&bn, &rn);
        for (j = 0; j < 3; j++) {
            b_mat.m[0][j] += w[i] * outer.m[0][j];
            b_mat.m[1][j] += w[i] * outer.m[1][j];
            b_mat.m[2][j] += w[i] * outer.m[2][j];
        }
    }

    // 3. Construct Davenport Matrix K
    double sigma = b_mat.m[0][0] + b_mat.m[1][1] + b_mat.m[2][2];
    double z[3];
    z[0] = b_mat.m[1][2] - b_mat.m[2][1];
    z[1] = b_mat.m[2][0] - b_mat.m[0][2];
    z[2] = b_mat.m[0][1] - b_mat.m[1][0];

    double k[4][4] = {{0}};

    // K(0,0) = sigma
    k[0][0] = sigma;

    // Off-diagonals involving z
    for (i = 0; i < 3; i++) {
        k[0][i+1] = z[i];
        k[i+1][0] = z[i];
    }

    // Lower right 3x3 block: B + B^T - sigma*I
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            double val = b_mat.m[i][j] + b_mat.m[j][i];
            if (i == j) {
                val -= sigma;
            }
            k[i+1][j+1] = val;
        }
    }

    // Add 3 * sum(weights) to diagonal
    double diag_offset = 3.0 * weight_sum;
    for (i = 0; i < 4; i++) {
        k[i][i] += diag_offset;
    }

    // 4. Power iteration to find dominant eigenvector
    double v[4] = {1.0, 0.0, 0.0, 0.0};
    double next[4];
    int converged = 0;

    for (size_t iter = 0; iter < ADCS_MAX_ITERATIONS; iter++) {
        double norm_sq = 0.0;

        // Matrix-vector multiplication next = K * v
        for (i = 0; i < 4; i++) {
            next[i] = 0.0;
            for (j = 0; j < 4; j++) {
                next[i] += k[i][j] * v[j];
            }
            norm_sq += next[i] * next[i];
        }

        double norm = sqrt(norm_sq);
        if (norm <= ADCS_EPS_NORM) {
            *out = identity;
            return ADCS_E_DEGENERATE;
        }

        // Normalize
        double diff = 0.0;
        for (i = 0; i < 4; i++) {
            next[i] /= norm;
            diff += fabs(next[i] - v[i]);
            v[i] = next[i];
        }

        if (diff < 1.0e-13) {
            converged = 1;
            break;
        }
    }

    // 5. Form quaternion and canonicalize
    adcs_quat_t result = {v[0], v[1], v[2], v[3]};

    // Ensure unit length just in case of numerical drift
    adcs_status_t stat = adcs_quat_normalize(&result, out);
    if (stat != ADCS_OK) {
        *out = identity;
        return ADCS_E_DEGENERATE;
    }

    // Canonicalize: w >= 0
    if (out->w < 0.0) {
        out->w = -out->w;
        out->x = -out->x;
        out->y = -out->y;
        out->z = -out->z;
    }

    return converged ? ADCS_OK : ADCS_E_NO_CONVERGENCE;
}

